(4927567, 716324, 30049, '<td valign="top">Morning outtake?  :-)</td>', 'Morning outtake?  :-)', '2008-09-02 11:12:44.000000', NULL, 1),
(4927569, 713139, 30049, '<td valign="top">There seems to be a strong bluish colorcast to this.  May want to adjust the color temp to something a tad warmer.  JMO of course.  :-)  Good luck.</td>', 'There seems to be a strong bluish colorcast to this.  May want to adjust the color temp to something a tad warmer.  JMO of course.  :-)  Good luck.', '2008-09-02 11:16:08.000000', NULL, 1),
(4927570, 714959, 3102, '<td valign="top">This is a great composition for a shot, but in order to pull this off, it just HAS to be sharper.  At the very least, the eyes need to be in perfect focus.</td>', 'This is a great composition for a shot, but in order to pull this off, it just HAS to be sharper.  At the very least, the eyes need to be in perfect focus.', '2008-09-02 11:16:18.000000', NULL, 1),
(4927572, 714848, 30049, '<td valign="top">Wonderful capture!</td>', 'Wonderful capture!', '2008-09-02 11:16:49.000000', NULL, 1),
(4927573, 715710, 30049, '<td valign="top">Horse(s) outtake?  :-)  Nice shot overall.  Seems to be just a wee bit of motion blur?</td>', 'Horse(s) outtake?  :-)  Nice shot overall.  Seems to be just a wee bit of motion blur?', '2008-09-02 11:18:35.000000', NULL, 1),
(4927575, 716327, 30049, '<td valign="top">Very well captured portrait here.  Nice!</td>', 'Very well captured portrait here.  Nice!', '2008-09-02 11:19:43.000000', NULL, 1),
