(4927594, 717055, 92864, '<td valign="top">Lovely.</td>', 'Lovely.', '2008-09-02 11:46:01.000000', NULL, 1),
(4927595, 716587, 30049, '<td valign="top">Too bad this isn''t sharply focused.   The colors are wonderful.</td>', 'Too bad this isn''t sharply focused.   The colors are wonderful.', '2008-09-02 11:46:11.000000', NULL, 1),
(4927596, 715799, 81530, '<td valign="top">I think this might work better as a square crop.</td>', 'I think this might work better as a square crop.', '2008-09-02 11:46:15.000000', NULL, 1),
(4927603, 713109, 92864, '<td valign="top">I love it!</td>', 'I love it!', '2008-09-02 11:51:26.000000', NULL, 1),
(4927630, 716730, 58272, '<td valign="top">Has a tangibly soft and fluffy feel :P<br/>Nice use of DOF, would like it if the eyes were a tad sharper.</td>', 'Has a tangibly soft and fluffy feel :PNice use of DOF, would like it if the eyes were a tad sharper.', '2008-09-02 12:20:25.000000', NULL, 1),
(4927639, 711956, 58272, '<td valign="top">I really like the misty, tranquil feeling here. I''d like to see this taken  from a lower perspective.</td>', 'I really like the misty, tranquil feeling here. I''d like to see this taken  from a lower perspective.', '2008-09-02 12:23:04.000000', NULL, 1),
(4927647, 716339, 58272, '<td valign="top">The colours on the rocks and sand here don''t seem quite right.....</td>', 'The colours on the rocks and sand here don''t seem quite right.....', '2008-09-02 12:25:27.000000', NULL, 1),
(4927663, 708375, 79720, '<td valign="top">I like the bokeh, a bit more contrast/brightness would have helped.</td>', 'I like the bokeh, a bit more contrast/brightness would have helped.', '2008-09-02 12:37:27.000000', NULL, 1),
(4927667, 712924, 79720, '<td valign="top">A nice concept. Maybe with an additional, off-camera light source to highlight the eyes differently, and create some visual confusion.</td>', 'A nice concept. Maybe with an additional, off-camera light source to highlight the eyes differently, and create some visual confusion.', '2008-09-02 12:39:55.000000', NULL, 1),
(4927671, 712789, 79720, '<td valign="top">You''ve resized it too small, the brown bit in the upper-left corner should have been cropped. The direct, on-camera flash is probably not the best choice for lighting this one.</td>', 'You''ve resized it too small, the brown bit in the upper-left corner should have been cropped. The direct, on-camera flash is probably not the best choice for lighting this one.', '2008-09-02 12:41:13.000000', NULL, 1),
