INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4940312, 715856, 50695, '<td valign="top">Fantastic energy to this picture.</td>', 'Fantastic energy to this picture.', '2008-09-07 19:26:53.000000', NULL, 1),
(4940313, 716746, 50695, '<td valign="top">Amazing effect. 8</td>', 'Amazing effect. 8', '2008-09-07 19:27:09.000000', NULL, 1),
(4940324, 716177, 50695, '<td valign="top">Wonderful and hilarious. 9</td>', 'Wonderful and hilarious. 9', '2008-09-07 19:33:36.000000', NULL, 1),
(4940326, 716002, 50695, '<td valign="top">Fascinating, mysterious image.</td>', 'Fascinating, mysterious image.', '2008-09-07 19:34:00.000000', NULL, 1),
(4940329, 716693, 50695, '<td valign="top">You make the difficult look easy. You make the absurd look inevitable.</td>', 'You make the difficult look easy. You make the absurd look inevitable.', '2008-09-07 19:34:46.000000', NULL, 1),
(4940336, 707584, 86316, '<td valign="top">Beautiful. 9</td>', 'Beautiful. 9', '2008-09-07 19:38:29.000000', NULL, 1),
(4940344, 708562, 86316, '<td valign="top">Gorgeous. 9</td>', 'Gorgeous. 9', '2008-09-07 19:41:51.000000', NULL, 1),
(4940353, 714219, 97441, '<td valign="top">Brilliant rendering.  One of the best draganized portraits I''ve seen.</td>', 'Brilliant rendering.  One of the best draganized portraits I''ve seen.', '2008-09-07 19:45:33.000000', NULL, 1),
(4940394, 716908, 64446, '<td valign="top">Neat! The reflections are a very nice touch...</td>', 'Neat! The reflections are a very nice touch...', '2008-09-07 20:07:18.000000', NULL, 1),
(4940451, 715331, 43774, '<td valign="top">I love the sense of scale here given by the shoes. This is such a wonderful, artistic photo.</td>', 'I love the sense of scale here given by the shoes. This is such a wonderful, artistic photo.', '2008-09-07 20:35:24.000000', NULL, 1),
(4940455, 716950, 43774, '<td valign="top">Dramatic, it feels like I am soaring over the mountains.</td>', 'Dramatic, it feels like I am soaring over the mountains.', '2008-09-07 20:35:50.000000', NULL, 1),
(4940457, 710977, 43774, '<td valign="top">Is this in the Rockies? A beautiful photo, the different colours in the water are wonderful.</td>', 'Is this in the Rockies? A beautiful photo, the different colours in the water are wonderful.', '2008-09-07 20:36:23.000000', NULL, 1),
(4940460, 716212, 43774, '<td valign="top">Very nice, great clarity, good pose and composition. I''ve never seen a Kite before.</td>', 'Very nice, great clarity, good pose and composition. I''ve never seen a Kite before.', '2008-09-07 20:36:55.000000', NULL, 1),
(4940461, 716476, 43774, '<td valign="top">Really nice composition, I like the reflections in the shallow water. I like the tones too.</td>', 'Really nice composition, I like the reflections in the shallow water. I like the tones too.', '2008-09-07 20:37:23.000000', NULL, 1),
(4940464, 716317, 43774, '<td valign="top">Surreal, great job!</td>', 'Surreal, great job!', '2008-09-07 20:37:36.000000', NULL, 1),
(4940466, 716367, 43774, '<td valign="top">Beautiful job on framing this, good exposure.</td>', 'Beautiful job on framing this, good exposure.', '2008-09-07 20:37:56.000000', NULL, 1),
(4940467, 715786, 43774, '<td valign="top">A beautiful cityscape, so much to see.</td>', 'A beautiful cityscape, so much to see.', '2008-09-07 20:38:22.000000', NULL, 1),
(4940468, 715799, 43774, '<td valign="top">Wonderful colours in the sky and I love the ripples caused by the swans.</td>', 'Wonderful colours in the sky and I love the ripples caused by the swans.', '2008-09-07 20:38:49.000000', NULL, 1),
(4940470, 716597, 43774, '<td valign="top">Majestic landscape, nice!</td>', 'Majestic landscape, nice!', '2008-09-07 20:39:15.000000', NULL, 1),
(4940485, 714189, 30982, '<td valign="top">You may get comments that it would be better to have the horse not leaving the frame, but I disagree.  It adds to the freedom and power that is a horse to have it leave the frame.  I love the toning of this - very powerful shot.</td>', 'You may get comments that it would be better to have the horse not leaving the frame, but I disagree.  It adds to the freedom and power that is a horse to have it leave the frame.  I love the toning of this - very powerful shot.', '2008-09-07 20:45:34.000000', NULL, 1),
(4940489, 713202, 30982, '<td valign="top">My kind of shot.  I like the anonymity of it with his face hidden by the umbrella, and the sheer amount of water falling.</td>', 'My kind of shot.  I like the anonymity of it with his face hidden by the umbrella, and the sheer amount of water falling.', '2008-09-07 20:46:29.000000', NULL, 1),
(4940491, 717058, 30982, '<td valign="top">Awww - cat knows a good thing when it finds it.  Warm and lovely shot!</td>', 'Awww - cat knows a good thing when it finds it.  Warm and lovely shot!', '2008-09-07 20:46:59.000000', NULL, 1),
(4940493, 716357, 76598, '<td valign="top">I like the idea, somehow it isn''t working well.  Perhaps a side shot rather than face on would have worked better.</td>', 'I like the idea, somehow it isn''t working well.  Perhaps a side shot rather than face on would have worked better.', '2008-09-07 20:47:07.000000', NULL, 1),
(4940494, 716513, 30982, '<td valign="top">Wonderful kitty portrait and very powerful in B&amp;W.</td>', 'Wonderful kitty portrait and very powerful in B&W.', '2008-09-07 20:47:20.000000', NULL, 1),
(4940496, 712789, 76598, '<td valign="top">use all your pixels....this looks like a very good picture, but it is too small to see</td>', 'use all your pixels....this looks like a very good picture, but it is too small to see', '2008-09-07 20:47:53.000000', NULL, 1),
(4940499, 713884, 76598, '<td valign="top">Very nice, I would have cropped some of the dark area down</td>', 'Very nice, I would have cropped some of the dark area down', '2008-09-07 20:48:46.000000', NULL, 1),
(4940500, 716943, 30982, '<td valign="top">I like this - like the overexposed background and the crop/framing.</td>', 'I like this - like the overexposed background and the crop/framing.', '2008-09-07 20:49:24.000000', NULL, 1),
(4940502, 713613, 30982, '<td valign="top">This looks like one of the Missions in San Antonio though I''d have to check my own shots to remember which one.  I can pictue it in my head quite clearly - just not the name!  Nice job with the composition and color.</td>', 'This looks like one of the Missions in San Antonio though I''d have to check my own shots to remember which one.  I can pictue it in my head quite clearly - just not the name!  Nice job with the composition and color.', '2008-09-07 20:50:11.000000', NULL, 1),
(4940503, 714887, 30982, '<td valign="top">Nice minimalistic shot - I like the sweeping curves of the water.</td>', 'Nice minimalistic shot - I like the sweeping curves of the water.', '2008-09-07 20:50:34.000000', NULL, 1),
(4940506, 716260, 76598, '<td valign="top">I would prefer the baby further up into the image</td>', 'I would prefer the baby further up into the image', '2008-09-07 20:51:16.000000', NULL, 1),
(4940508, 714341, 30982, '<td valign="top">Lovely shallow DOF and really nice pastel tones throughout.  I like the way the three in the foreground are sort of echoed by those in the distance.</td>', 'Lovely shallow DOF and really nice pastel tones throughout.  I like the way the three in the foreground are sort of echoed by those in the distance.', '2008-09-07 20:51:57.000000', NULL, 1),
(4940509, 715778, 30982, '<td valign="top">Wonderfully crisp photojournalism shot - great job minimizing the background and highlighting your subject.</td>', 'Wonderfully crisp photojournalism shot - great job minimizing the background and highlighting your subject.', '2008-09-07 20:52:32.000000', NULL, 1),
(4940513, 708422, 76598, '<td valign="top">the angled "defocus" appears odd</td>', 'the angled "defocus" appears odd', '2008-09-07 20:56:41.000000', NULL, 1),
(4940515, 716944, 30982, '<td valign="top">What a great look you captured!  Looks like a young one, yes?</td>', 'What a great look you captured!  Looks like a young one, yes?', '2008-09-07 20:57:18.000000', NULL, 1),
(4940516, 716298, 30982, '<td valign="top">Very nice expansive view, great capture/processing to really make this shine.</td>', 'Very nice expansive view, great capture/processing to really make this shine.', '2008-09-07 20:57:51.000000', NULL, 1),
(4940519, 714161, 30982, '<td valign="top">Lovely portrait!  Color is well done to echo the lavender of her shadow and pupil.  Excellent composition.</td>', 'Lovely portrait!  Color is well done to echo the lavender of her shadow and pupil.  Excellent composition.', '2008-09-07 20:58:27.000000', NULL, 1),
(4940520, 716900, 30982, '<td valign="top">Really nice processing to make this almost fairytale-like.</td>', 'Really nice processing to make this almost fairytale-like.', '2008-09-07 20:58:50.000000', NULL, 1),
